def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    Q = int(data[2])

    scores = [K] * N
    adjustments = defaultdict(int)

    index = 3
    for _ in range(Q):
        player = int(data[index]) - 1
        index += 1

        if scores[player] > 0:
            scores[player] -= 1
            adjustments[player] += 1

            for i in range(N):
                if i != player and scores[i] > 0:
                    scores[i] -= adjustments[player]
                    adjustments[i] += adjustments[player]

    for score in scores:
        if score <= 0:
            print("No")
        else:
            print("Yes")

if __name__ == "__main__":
