import sys

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    Q = int(data[2])

    players = [K] * N

    for i in range(Q):
        player_index = int(data[3 + i]) - 1
        players[player_index] -= 1

        for j in range(1, N):
            prev_player = (player_index - j + N) % N
            next_player = (player_index + j) % N

            if players[prev_player] > 0:
                players[prev_player] -= 1
            if players[next_player] > 0:
                players[next_player] -= 1

    for score in players:
        if score <= 0:
            print("No")
        else:
            print("Yes")

if __name__ == "__main__":
    main()
